const materialLabels={none:'No Materials',books:'Books',paper:'Paper & Drawing',toys:'Toys',household:'Household Items',outdoor:'Outdoor Space',device:'Device Optional'};
let activityFilters={time:'all',materials:'all'};
function routineLabel(type){return {morning:'Morning',afternoon:'Afternoon',evening:'Bedtime'}[type]||type}
function activityDetails(age,i){const a=activitySupports[age][i],time=stages[age][2][i].split('|')[2];return `<dl class="activity-facts"><dt>Suggested Age Range</dt><dd>${esc(stages[age][0])}</dd><dt>Time Needed</dt><dd>${esc(time)} · shorten or split it as needed</dd><dt>Materials</dt><dd>${esc(a.materials)}</dd></dl><details class="activity-adaptations"><summary>Ways To Adapt</summary><p><strong>Quieter Option:</strong> ${esc(a.quiet)}</p><p><strong>Movement Or Rest Break:</strong> ${esc(a.movement)}</p><p><strong>Communication &amp; Participation:</strong> ${esc(a.communication)}</p></details>`}
function filteredActivities(){const pool=state.support[scope()]?[0]:activityFilters.time==='all'&&activityFilters.materials==='all'?activityChoices:stages[state.age][2].map((_,i)=>i);const matches=pool.filter(i=>{const minutes=parseInt(stages[state.age][2][i].split('|')[2]);return (activityFilters.time==='all'||minutes<=Number(activityFilters.time))&&(activityFilters.materials==='all'||activitySupports[state.age][i].category===activityFilters.materials)});return matches.length?[matches[Math.abs(offset)%matches.length]]:[]} 
function activityFilterControls(){return `<div class="activity-filters"><label>Time Available<select data-activity-filter="time"><option value="all">Any Time</option>${[5,10,15,20,30,45].map(n=>`<option value="${n}" ${activityFilters.time===String(n)?'selected':''}>Up To ${n} Minutes</option>`).join('')}</select></label><label>Materials<select data-activity-filter="materials"><option value="all">Any Materials</option>${Object.entries(materialLabels).map(([key,label])=>`<option value="${key}" ${activityFilters.materials===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label></div>`}

const multiplesPlans=[{"activity": "Offer one short hello or story to each baby in turn, with another caregiver helping when available. Each baby can pause at different times.", "routines": ["Keep a separate simple care note for each baby", "Reset one shared supply basket between care rounds", "Agree on who handles the next care round and who takes a break"], "jobs": ["Caregiver: label and organize each baby’s everyday supplies"], "tip": "A shared plan can organize the day without expecting babies to have identical needs."}, {"activity": "Offer each baby their own age-safe toy or board-book turn. Sit close, watch individual interest, and pause separately.", "routines": ["Set out each baby’s supplies before starting the care round", "Rotate short play turns without expecting matching responses", "Share a brief note about each baby’s day with the next caregiver"], "jobs": ["Caregiver: reset each baby’s play materials"], "tip": "Keep individual preferences visible, even when much of the day is shared."}, {"activity": "Try a color hunt together, or give each toddler their own large-block area. Waiting, parallel play, and joining an adult all count.", "routines": ["Offer each toddler their own simple clothing choice", "Give each child one toy basket to reset with an adult", "Read together or give each child a short separate story turn"], "jobs": ["Put one toy in your own basket with help"], "tip": "Use duplicate or similar materials when useful, and keep turn-taking short."}, {"activity": "Make a shared silly story with a drawing space for each child. They can draw side by side, tell separate endings, or pass a turn.", "routines": ["Use one picture plan with a separate choice for each child", "Give each child a small cleanup zone and adult support", "Offer a shared story followed by an individual goodnight"], "jobs": ["Choose a small cleanup zone; swap tomorrow if wanted"], "tip": "Make space for separate interests instead of comparing finished work."}, {"activity": "Create a family comic with one panel per child, or make separate comics. Offer the same materials without requiring the same result.", "routines": ["Check each child’s bag with their own short checklist", "Agree on separate jobs or homework starting steps", "Let each child choose a book or quiet wind-down option"], "jobs": ["Choose one manageable table or toy job with a clear turn"], "tip": "Rotate shared jobs fairly, but adjust support to each child’s abilities."}, {"activity": "Design a game together with optional roles: artist, rule writer, or tester. Let each child choose a role or work on a separate idea.", "routines": ["Review each child’s schedule rather than assuming they match", "Offer shared downtime and separate schoolwork plans", "Let each child choose their own preparation step for tomorrow"], "jobs": ["Agree on one household contribution and the support needed"], "tip": "Shared ages do not mean identical schedules, interests, or independence."}, {"activity": "Invite each teen to choose a creative project or one playlist suggestion. They can participate separately and decide what to share.", "routines": ["Check each teen’s plans privately when preferred", "Agree on chores and recovery time with each teen", "Respect separate wind-down choices and boundaries"], "jobs": ["Choose an agreed household task without comparing siblings"], "tip": "Give each teen room for separate friendships and decisions."}, {"activity": "Plan a simple meal with optional roles chosen by each teen, or do separate life-skill projects. Agree on supervision and tools for each person.", "routines": ["Check individual work, study, or transport commitments", "Agree on each person’s contribution and rest time", "Ask what help each teen wants for tomorrow"], "jobs": ["Agree on one life-skill or household contribution individually"], "tip": "Plan with each teen; one sibling does not need to manage the other."}, {"activity": "Offer a shared meal or check-in, with individual invitations. Each adult chooses whether to join and what support they want.", "routines": ["Respect each adult’s own schedule and chosen reminders", "Agree on shared responsibilities only where relevant", "Choose a realistic way to connect without assuming matching plans"], "jobs": ["Agree on shared household responsibilities with everyone’s consent"], "tip": "Keep relationships individual while making room for shared family connection."}];
function multiplesEnabled(){return state.multiplesMode===true}
function multiplesPanel(){if(!multiplesEnabled())return '';const p=multiplesPlans[state.age];return `<section class="card multiples-plan"><p class="kicker">TWINS, TRIPLETS &amp; MORE</p><h3>Little Wins For Your Multiples</h3><p class="fine">${esc(stages[state.age][0])} · group planning ideas, with room for each child.</p><p>${esc(p.tip)}</p>${tab==='activities'?`<p><strong>Try It Together Or Side By Side:</strong> ${esc(p.activity)}</p>`:tab==='responsibilities'?'<p>Give each child a clear, manageable job. Similar effort can look different for different abilities.</p>':'<p>Share a routine when it helps; make individual choices and pause at each child’s pace. Multiples steps are included in the checklists below.</p>'}<p class="fine">For siblings in different stages, switch the age selector to explore ideas for each. This group option does not add separate child profiles.</p><a href="https://littlewinsparentclub.com/mothers-of-multiples.html">Read Mothers Of Multiples Guides</a></section>`}

const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={age:3,selected:null,children:[],lists:{},checks:{},support:{}};try{const s=JSON.parse(localStorage.getItem('littleWins.v1'));if(s&&Array.isArray(s.children)&&s.lists&&s.checks)state={...state,...s}}catch{};if(!state.support||typeof state.support!=='object')state.support={};if(!stages[state.age])state.age=3;const timerUI={sound:false,audio:null,message:'Visual alerts are ready. Enable sound if you want an audible alarm.'};const companionSync={ready:false,busy:false,conflict:false,loadFailed:false,version:0,last:'',timer:null};let ideaCatalog=[],recipeCatalog=[];let tab='today',offset=0;let mealTaskView=false;let chosenMealId='';let day='',seed=0;
function setDay(){const d=new Date();day=[d.getFullYear(),d.getMonth()+1,d.getDate()].join('-');seed=Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000);$('date').textContent=d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});if($('motivation'))$('motivation').textContent=encouragement[seed%encouragement.length]}
function save(){queueCompanionSave();try{localStorage.setItem('littleWins.v1',JSON.stringify(state));if((companionSync.ready||companionSync.loadFailed)&&JSON.stringify(state)!==companionSync.last)localStorage.setItem('littleWins.pending',JSON.stringify({baseVersion:companionSync.version,data:state}))}catch{$('storageNote').textContent='Browser storage is unavailable. Changes will last only until this page closes.'}}
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2500)}
function scope(){return state.selected||'stage-'+state.age}function listKey(type){return (type.startsWith('parent-')?'parent':scope())+(type.startsWith('parent-')?'':(state.support[scope()]?':supported':'')+(multiplesEnabled()?':multiples':''))+':'+type}function getList(type){const k=listKey(type);if(!state.lists[k]){const source=parentCare[type]|| (type==='responsibilities'?(state.support[scope()]?supportPlans[state.age].jobs:stages[state.age][3]):(state.support[scope()]?supportPlans[state.age].routines:stages[state.age][4])[['morning','afternoon','evening'].indexOf(type)]);const extra=!type.startsWith('parent-')&&multiplesEnabled()?(type==='responsibilities'?multiplesPlans[state.age].jobs:[multiplesPlans[state.age].routines[['morning','afternoon','evening'].indexOf(type)]].filter(Boolean)):[];state.lists[k]=[...source,...extra].map((text,i)=>({id:'default-'+i,text}))}return state.lists[k]}
function checked(type,id){return !!state.checks[day+':'+listKey(type)+':'+id]}function toggle(type,id,value){if(!getList(type).some(t=>t.id===id))throw Error('Task not found');state.checks[day+':'+listKey(type)+':'+id]=value;save();render()}
function chooseStage(age,child=null){if(child&&state.children[0]?.id!==child){showPackagePreview('profiles');return}if(!Number.isInteger(age)||!stages[age])throw Error('Invalid stage');state.age=age;state.selected=child;offset=0;activityChoices=nextActivitySet(age);save();render()}
let unifiedFavoriteItems=[],favoriteFilter='all';let favoriteItems=[],favoriteStatus='Loading your saved activities…';const activityDecks=new Map();
function shuffled(list){const out=[...list];for(let i=out.length-1;i>0;i--){const n=new Uint32Array(1);crypto.getRandomValues(n);const j=n[0]%(i+1);[out[i],out[j]]=[out[j],out[i]]}return out}
function nextActivitySet(age,count=1){let deck=activityDecks.get(age)||[];const chosen=[];while(chosen.length<count){if(!deck.length)deck=shuffled(stages[age][2].map((_,i)=>i).filter(i=>!chosen.includes(i)&&(!state.setup?.quiet||!/(clap|rhythm|voice duet)/i.test(stages[age][2][i]))));chosen.push(deck.shift())}activityDecks.set(age,deck);return chosen}
let activityChoices=nextActivitySet(state.age);
function isFavorite(age,index){return favoriteItems.some(x=>x.stage===age&&x.activity===index)}
async function loadFavorites(){try{const r=await fetch('/api/activities/favorites');const j=await r.json();if(!r.ok)throw Error(j.error);favoriteItems=j.items;favoriteStatus='Saved to your signed-in companion account.'}catch(e){favoriteStatus=e.message||'Favorites are unavailable. Please try again.'}render()}
async function changeFavorite(age,index){const exists=isFavorite(age,index);try{const r=await fetch('/api/activities/favorites',{method:exists?'DELETE':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stage:age,activity:index})});const j=await r.json();if(!r.ok)throw Error(j.error);favoriteItems=j.items;favoriteStatus='Saved to your signed-in companion account.';toast(exists?'Removed from favorites':'Saved to favorites');loadUnifiedFavorites();render()}catch(e){toast(e.message||'Favorite could not be saved. Please try again.')}}
function activity(i,age=state.age){const [title,body,time]=stages[age][2][i].split('|');const done=age===state.age&&checked('activities','a'+i);const favorite=isFavorite(age,i);return `<article class="card activity-card"><span class="kicker">PLAY & CONNECT</span><h3>${esc(title)}</h3><p>${esc(body)}</p>${activityDetails(age,i)}${multiplesEnabled()?`<p class="multiples-activity-tip"><strong>For Multiples:</strong> ${esc(multiplesPlans[age].activity)}</p>`:''}${state.support[scope()]?'<p class="support-tip"><strong>Make It Comfortable:</strong> Offer one step at a time, allow a pause, and welcome gestures or words. Follow your child’s preferences; participation is optional.</p>':''}<div class="activity-actions"><button class="favorite-button" data-favorite="${i}" data-age="${age}" aria-pressed="${favorite}">${favorite?'♥ Saved · remove':'♡ Save to favorites'}</button>${age===state.age?`<button type="button" data-timed-idea="${i}">Add To Today’s Little Wins</button><button class="${done?'secondary':'primary'}" data-act="${i}">${done?'✓ Completed · undo':'Mark activity complete'}</button>`:''}</div></article>`}
function taskCard(type,title,add=true){const fullList=getList(type),list=state.support[scope()]&&type==='responsibilities'?fullList.slice(0,1):fullList,n=list.filter(t=>checked(type,t.id)).length;const markup=`<article class="card"><span class="kicker">${type.startsWith('parent-')?'CARE FOR YOU':type==='responsibilities'?'GROW TOGETHER':'DAILY RHYTHM'}</span><h3>${title}</h3><div class="fine">${n} of ${list.length} complete today</div><div class="progress" role="progressbar" aria-label="${title} progress" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${list.length}"><div style="width:${list.length?n/list.length*100:0}%"></div></div>${list.map((t,i)=>`<div class="check-row ${checked(type,t.id)?'done':''}"><input type="checkbox" id="${type}-${i}" data-type="${type}" data-id="${esc(t.id)}" ${checked(type,t.id)?'checked':''}><label for="${type}-${i}">${esc(t.text)}</label>${add?`<button data-remove="${esc(t.id)}" data-list="${type}" aria-label="Remove ${esc(t.text)}">×</button>`:''}</div>`).join('')}${list.length?'':'<p>No tasks yet. Add what works for your family.</p>'}${add?`<form class="add-task" data-list="${type}"><input maxlength="120" aria-label="New ${type} task" placeholder="Add your own task" required><button type="submit">Add</button></form>`:''}</article>`;if(['morning','afternoon','evening'].includes(type))return markup.replace('<h3>'+title+'</h3>','<details class="routine-fold" '+(type==='morning'?'open':'')+'><summary>'+title+'</summary>').replace('</article>','</details></article>');return markup;}
function render(){organizeSections(tab);$('parent-club-section').hidden=tab!=='club';if(tab==='club')loadParentClub();if(state.selected&&state.children[0]&&state.selected!==state.children[0].id){state.selected=state.children[0].id;state.age=state.children[0].age}if(['journal','selfcare'].includes(tab)){showPackagePreview(tab);return}setDay();$('today-content').hidden=tab!=='today';$('meal-prep-section').hidden=tab!=='meals';$('parent-journal').hidden=tab!=='journal';$('content').hidden=['journal','today','meals','club'].includes(tab);$('stage-panel').hidden=!['activities','routines','responsibilities'].includes(tab);document.querySelectorAll('.app-parent-header,.app-photo-credit,.planner-title').forEach(el=>el.hidden=true);document.querySelectorAll('.intro,.restored-laugh,.access-controls').forEach(el=>el.hidden=tab!=='today');$('multiplesMode').checked=multiplesEnabled();$('neuroSupport').checked=!!state.support[scope()];$('age').value=state.age;const c=state.children.find(c=>c.id===state.selected);$('childNote').textContent=c?`Today’s plan for ${c.name}.`:'Explore a stage, or add your children in My family.';$('children').innerHTML=state.children.slice(0,1).map(c=>`<button class="chip ${c.id===state.selected?'selected':''}" data-child="${esc(c.id)}">${esc(c.name)}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',(b.dataset.mainSection==='family'?['routines','activities','responsibilities'].includes(tab):b.closest('.header-planner-nav')&&b.dataset.tab==='selfcare'?['selfcare','journal'].includes(tab):b.dataset.tab===tab));b.setAttribute('aria-pressed',String((b.dataset.mainSection==='family'?['routines','activities','responsibilities'].includes(tab):b.closest('.header-planner-nav')&&b.dataset.tab==='selfcare'?['selfcare','journal'].includes(tab):b.dataset.tab===tab)))});renderDailySections();const head=`<div class="section-head"><div><h2>${({today:'Your daily little wins',activities:'Make a little room for play',meals:'Meal Prep & Recipes',favorites:'Your Favorites',routines:'A rhythm that works for you',responsibilities:'Little jobs. Growing confidence.',selfcare:'Parent Self-Care',journal:'Parent Journal'})[tab]}</h2><p>${tab==='today'?'Your goals, your pace. Keep today’s plan small and flexible.':tab==='selfcare'?'Flexible morning and night routines for the grown-ups.':esc(stages[state.age][1])}</p></div>${''}</div>`;let body='';if(tab==='today'){body=''}else if(tab==='club'){body=''}else if(tab==='activities')body=`<div class="activity-toolbar"><p>${state.support[scope()]?'One adapted activity for this stage is included free.':'One idea at a time. Shuffle, save it, or add it to your day.'}</p>${state.support[scope()]?'<a href="membership.html#planner-preview">Preview More Supported Activities</a>':'<button id="shuffleActivities">Shuffle Another Activity</button>'}</div>${activityFilterControls()}<div class="activity-grid">${filteredActivities().map(i=>activity(i)).join('')||'<p class="card">No activities match these filters. Choose more time or different materials.</p>'}</div>`;else if(tab==='favorites')body=unifiedFavoritesView();else if(tab==='routines')body=`<p class="fine">Free Little Wins includes ready-to-use morning, afternoon, and bedtime routines. Check off steps at your own pace. Custom tasks are part of Family Planner.</p><div class="routine-grid">${state.support[scope()]?taskCard('morning','A Gentle Supported '+routineLabel('morning'),false):taskCard('morning',routineLabel('morning'),false)+taskCard('afternoon',routineLabel('afternoon'),false)+taskCard('evening',routineLabel('evening'),false)}</div>`;else if(tab==='selfcare')body=`<article class="card selfcare-intro"><span class="kicker">YOU COUNT, TOO</span><h3>Start small. Leave room for real life.</h3><p>Aim for about 10 minutes, split up if needed. This checklist is an invitation, not another measure of how well you’re doing.</p><p><strong>Only have two minutes?</strong> Morning: a sip of water, a quick wash, and one kind thought. Night: brush your teeth, name a little win, and pause. Rest can be the win.</p><p class="fine">Keep children safely cared for during breaks. These are personal-care ideas, not a treatment plan.</p></article><div class="grid">${taskCard('parent-morning','Morning · a gentle start')}${taskCard('parent-night','Night · set it down')}</div><p class="fine">Your self-care checklist stays the same when you switch children or age stages. Checkmarks start fresh each day.</p>`;else if(tab==='journal')body='';else body=`<p>Choose jobs that fit your child’s skills and preferences. Start together, offer support, and celebrate the effort.</p>${taskCard('responsibilities','Our Responsibilities',false)}<p class="fine">These basic responsibilities are included free. Family Planner adds custom tasks and multiple-child profiles.</p>`;if(tab==='routines')body=startingSetup()+body+'<p class="resource-reading"><a href="membership.html#circle-preview">Preview Family Circle</a></p>';if(tab==='routines')body+='<p class="resource-reading"><a href="https://littlewinsparentclub.com/family-support.html">Explore Wonderfully Wired: The Neurodivergent Minds Resources</a></p>';if(tab==='selfcare')body+='<p class="resource-reading"><a href="https://littlewinsparentclub.com/articles/parent-self-care.html">Read Parent Self-Care &amp; Mental Health Resources</a></p>';if(state.support[scope()]&&['routines','activities','responsibilities'].includes(tab))body='<p class="support-free-note">Free support includes one adapted activity, one morning routine, and one responsibility for this stage. <a href="membership.html#planner-preview">Preview More Support</a></p>'+body;if(['activities','routines','responsibilities'].includes(tab))body=multiplesPanel()+ideaPanel(tab)+body+importedIdeas(tab);$('content').innerHTML=head+body;save()}
const options=stages.map((s,i)=>`<option value="${i}">${esc(s[0])}</option>`).join('');$('age').innerHTML=options;$('childAge').innerHTML=options;$('childAge').value=3;
$('age').onchange=e=>{chooseStage(Number(e.target.value));scrollToCompanionSection()};$('children').onclick=e=>{const b=e.target.closest('[data-child]');if(b){const c=state.children.find(c=>c.id===b.dataset.child);if(c)chooseStage(c.age,c.id)}};document.querySelectorAll('nav').forEach(nav=>{nav.onclick=e=>{const button=e.target.closest('[data-tab]');if(button){mealTaskView=false;tab=button.dataset.tab;if(tab==='favorites')loadUnifiedFavorites();render();const menu=document.querySelector('.app-menu');if(menu)menu.open=false;scrollToCompanionSection(!!button.closest('.header-planner-nav'))}}});
$('content').oninput=e=>{if(hubInput(e))return;if(['dailyGoal','dailyDinner','mealIngredients'].includes(e.target.id)){captureDailyPlan();save()}};
$('content').onchange=e=>{if(hubChange(e))return;if(e.target.dataset.mealPrep){getDailyPlan().prep[e.target.dataset.mealPrep]=e.target.checked;save();return}if(e.target.dataset.dailyTodo){const plan=getDailyPlan(),item=plan.todos.find(x=>x.id===e.target.dataset.dailyTodo);if(item){item.done=e.target.checked;if(item.done&&item.timer)item.timer.status='stopped';save();renderDailySections()}return}if(e.target.matches('[data-type]'))toggle(e.target.dataset.type,e.target.dataset.id,e.target.checked)};
$('content').onclick=e=>{if(hubClick(e))return;const b=e.target.closest('button');if(!b)return;if(b.dataset.deleteTodo){captureDailyPlan();const plan=getDailyPlan();plan.todos=plan.todos.filter(x=>x.id!==b.dataset.deleteTodo);save();render();return}if(b.id==='nextIdea'||b.id==='shuffleActivities'){offset++;activityChoices=nextActivitySet(state.age);render();scrollToCompanionSection()}if(b.id==='reloadFavorites')loadFavorites();if(b.dataset.favorite!==undefined){changeFavorite(Number(b.dataset.age),Number(b.dataset.favorite));return}if(b.dataset.go){mealTaskView=false;tab=b.dataset.go;render();scrollToCompanionSection()}if(b.dataset.act!==undefined){const i=b.dataset.act;state.checks[day+':'+listKey('activities')+':a'+i]=!checked('activities','a'+i);save();render()}if(b.dataset.remove){state.lists[listKey(b.dataset.list)]=getList(b.dataset.list).filter(t=>t.id!==b.dataset.remove);save();render();toast('Task removed')}};
$('content').onsubmit=e=>{e.preventDefault();if(hubSubmit(e))return;const f=e.target;if(f.id==='dailyTodoForm'){captureDailyPlan();const input=f.querySelector('input'),text=input.value.trim(),plan=getDailyPlan();if(!text)return;if(plan.todos.length>=30){toast('Keep today’s list to 30 items or fewer.');return}plan.todos.push({id:crypto.randomUUID(),text:text.slice(0,120),done:false});save();render();return}if(!f.matches('.add-task'))return;const text=f.querySelector('input').value.trim();if(!text)return;getList(f.dataset.list).push({id:crypto.randomUUID(),text});save();render();toast('Task added')};
function familyList(){$('familyList').innerHTML=state.children.length?state.children.map(c=>`<div class="family-item"><div><strong>${esc(c.name)}</strong><div class="fine">${esc(stages[c.age][0])}</div></div><button type="button" data-delete-child="${esc(c.id)}">Remove</button></div>`).join(''):'<p class="fine">No children added yet. You can also explore any stage without adding a child.</p>'}
$('familyBtn').onclick=()=>{familyList();$('familyDialog').showModal()};$('closeDialog').onclick=()=>$('familyDialog').close();$('familyForm').onsubmit=e=>{e.preventDefault();if(state.children.length>=1){toast('One child profile is included. Explore other ages with Suggested Age Stage. Extra profiles are planned; packages are not available to buy yet.');return}const name=$('childName').value.trim();if(!name)return;const child={id:crypto.randomUUID(),name,age:Number($('childAge').value)};state.children.push(child);chooseStage(child.age,child.id);$('childName').value='';familyList();toast('Child added')};$('familyList').onclick=e=>{const b=e.target.closest('[data-delete-child]');if(!b)return;const id=b.dataset.deleteChild;state.children=state.children.filter(c=>c.id!==id);delete state.support[id];for(const k of Object.keys(state.lists))if(k.startsWith(id+':'))delete state.lists[k];for(const k of Object.keys(state.checks))if(k.includes(':'+id+':'))delete state.checks[k];if(state.selected===id)state.selected=state.children[0]?.id||null;save();familyList();render()};
const requestedView=new URLSearchParams(location.search).get('view');if(['today','activities','responsibilities','favorites','routines','selfcare','journal','meals','club'].includes(requestedView))tab=requestedView;if(location.hash==='#parent-journal')tab='journal';if(new URLSearchParams(location.search).has('meal'))tab='meals';render();if(requestedView==='family'){tab='routines';render();if(new URLSearchParams(location.search).get('edit')==='1'){familyList();$('familyDialog').showModal()}}setInterval(()=>{const previous=day;setDay();if(previous!==day)render()},30000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_parenting_stage',title:'Select parenting stage',description:'Change the visible planner to an age stage, indexed 0 newborn through 8 young adult.',inputSchema:{type:'object',properties:{stageIndex:{type:'integer',minimum:0,maximum:8}},required:['stageIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.stageIndex)||input.stageIndex<0||input.stageIndex>8)throw Error('Stage must be an integer from 0 to 8');chooseStage(input.stageIndex);return {stage:stages[state.age][0]}}})).catch(()=>{})}catch{}}

$('neuroSupport').onchange=e=>{state.support[scope()]=e.target.checked;save();render();toast(e.target.checked?'Support plan selected. Your original tasks are kept.':'Original plan selected. Your support tasks are kept.')};

loadFavorites();

function showPackagePreview(view){organizeSections(view);$('parent-club-section').hidden=true;$('today-content').hidden=true;$('meal-prep-section').hidden=true;const plan=['journal','selfcare'].includes(view)?'recharge':'planner';$('parent-journal').hidden=true;$('content').hidden=false;document.querySelectorAll('.app-parent-header,.app-photo-credit,.intro,.access-controls,.restored-laugh,.planner-title').forEach(el=>el.hidden=true);$('stage-panel').hidden=!['activities','routines','responsibilities','profiles'].includes(view);document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',(b.dataset.mainSection==='family'?['routines','activities','responsibilities'].includes(view):b.closest('.header-planner-nav')&&b.dataset.tab==='selfcare'?['selfcare','journal'].includes(view):b.dataset.tab===view));b.setAttribute('aria-pressed',String((b.dataset.mainSection==='family'?['routines','activities','responsibilities'].includes(view):b.closest('.header-planner-nav')&&b.dataset.tab==='selfcare'?['selfcare','journal'].includes(view):b.dataset.tab===view)))});$('content').innerHTML=`<article class="card"><p class="kicker">PACKAGE PREVIEW</p><h2>${plan==='recharge'?'Parent Recharge':'Family Planner'}</h2><p>${plan==='recharge'?'Self-care and a personal journal for $7.99/month. Add the optional fitness upgrade for $9.99/month total, with short workouts with or without equipment.':'Adaptable routines, custom responsibilities, and multiple-child profiles.'}</p><p>This is a package preview. Paid checkout and automatic email delivery are not connected yet. Subscriptions cannot be purchased, and newsletter emails are not sent automatically.</p><a class="primary package-cta" href="membership.html#${plan}-preview">See Package Preview</a><button data-go="today">Back To Today’s Little Wins</button></article>`;$('content').insertAdjacentHTML('beforeend',view==='selfcare'||view==='journal'?'<p class="resource-reading"><a href="https://littlewinsparentclub.com/articles/parent-self-care.html">Read Parent Self-Care &amp; Mental Health Resources</a></p>':'<p class="resource-reading"><a href="https://littlewinsparentclub.com/family-support.html">Explore Wonderfully Wired: The Neurodivergent Minds Resources</a></p>');const menu=document.querySelector('.app-menu');if(menu)menu.open=false;}

function getDailyPlan(){if(!state.dailyPlans||typeof state.dailyPlans!=='object'||Array.isArray(state.dailyPlans))state.dailyPlans={};let p=state.dailyPlans[day];if(!p||typeof p!=='object'||Array.isArray(p))p=state.dailyPlans[day]={goal:'',dinner:'',todos:[]};if(typeof p.goal!=='string')p.goal='';if(typeof p.dinner!=='string')p.dinner='';if(!Array.isArray(p.todos))p.todos=[];if(!p.prep||typeof p.prep!=='object'||Array.isArray(p.prep))p.prep={};if(typeof p.ingredients!=='string')p.ingredients='';p.todos=p.todos.filter(x=>x&&typeof x.id==='string'&&typeof x.text==='string');return p}
function captureDailyPlan(){const p=getDailyPlan();if($('dailyGoal'))p.goal=$('dailyGoal').value.slice(0,300);if(tab==='today'&&$('todayDinner'))p.dinner=$('todayDinner').value.slice(0,200);else if($('dailyDinner'))p.dinner=$('dailyDinner').value.slice(0,200);if($('mealIngredients'))p.ingredients=$('mealIngredients').value.slice(0,500)}
for(const id of ['today-content','meal-prep-section'])for(const event of ['onclick','onchange','oninput','onsubmit'])$(id)[event]=$('content')[event];

function companionStatus(text){if($('companionSyncStatus'))$('companionSyncStatus').textContent=text}
function queueCompanionSave(){if(!companionSync.ready||companionSync.conflict)return;clearTimeout(companionSync.timer);companionSync.timer=setTimeout(flushCompanionSave,600)}
async function flushCompanionSave(){if(!companionSync.ready||companionSync.busy||companionSync.conflict)return;const data=JSON.stringify(state);if(data===companionSync.last)return;companionSync.busy=true;companionStatus('Saving your plan…');try{const r=await fetch('/api/companion/plan',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:companionSync.version,data:JSON.parse(data)})});const j=await r.json();if(!r.ok){if(r.status===409){companionSync.conflict=true;$('loadSavedCompanion').hidden=false;}throw Error(j.error)}companionSync.version=j.version;companionSync.last=data;try{if(JSON.stringify(state)===data)localStorage.removeItem('littleWins.pending')}catch{}companionStatus('Your plan is saved to your signed-in account.');}catch(e){companionStatus((e.message||'Unable to save online.')+' Your draft stays on this device.');}finally{companionSync.busy=false;if(!companionSync.conflict&&companionSync.last!==JSON.stringify(state))companionSync.dirty=true;}if(companionSync.dirty){companionSync.dirty=false;if(companionSync.last===data)queueCompanionSave();}}
async function loadCompanion(){const main=document.querySelector('main');if(main)main.inert=true;companionStatus('Loading your saved plan…');try{const r=await fetch('/api/companion/plan');const j=await r.json();if(!r.ok)throw Error(j.error);try{const previous=localStorage.getItem('littleWins.account');if(j.accountKey&&previous&&previous!==j.accountKey){localStorage.setItem('littleWins.previousAccountDraft',JSON.stringify(state));localStorage.removeItem('littleWins.pending');state={age:3,selected:null,children:[],lists:{},checks:{},support:{}};}if(j.accountKey)localStorage.setItem('littleWins.account',j.accountKey);}catch{}let pending=null;try{pending=JSON.parse(localStorage.getItem('littleWins.pending'))}catch{};if(pending?.data&&pending.baseVersion!==j.version){companionSync.conflict=true;companionSync.version=pending.baseVersion;companionSync.ready=true;render();companionStatus('Your device draft and saved plan differ. Copy changes you want to keep, then use Load Saved Plan.');$('loadSavedCompanion').hidden=false;throw Error('Your device draft differs from the saved plan. Copy changes you want to keep, then choose Load Saved Plan.');}if(pending?.data)state=pending.data;else if(j.data){if(!Array.isArray(j.data.children)||!j.data.lists||!j.data.checks)throw Error('Your saved plan needs attention.');state={...state,...j.data};if(!state.support)state.support={};if(!stages[state.age])state.age=3;}companionSync.version=j.version;companionSync.ready=true;companionSync.last=j.data?JSON.stringify(j.data):'';setDay();render();companionStatus(j.data?'Your saved plan is ready.':'Your existing device plan will be saved to your account.');queueCompanionSave();}catch(e){companionSync.loadFailed=true;companionStatus((e.message||'Unable to load your saved plan.')+' Changes are device drafts until online saving is available.');}finally{if(main)main.inert=false;}try{const results=await Promise.all([fetch('idea-catalog.json').then(r=>r.json()),fetch('recipe-catalog.json').then(r=>r.json())]);if(!Array.isArray(results[0])||!Array.isArray(results[1]))throw Error('Invalid ideas or recipe list');ideaCatalog=results[0];recipeCatalog=results[1];const linkedIdea=ideaCatalog.find(x=>x.id===new URLSearchParams(location.search).get('idea'));if(linkedIdea)tab=ideaView(linkedIdea.kind);if(getDailyPlan().lowEnergy&&!getDailyPlan().lowEnergyRecipe)applyLowEnergyPlan();render();}catch{companionStatus('Ideas and recipes could not load. Reload to try again.');}}
function startingSetup(){if(state.setup?.done)return '';return `<section class="card first-use"><h2>A Small Starting Plan</h2><p>Choose the ages in your household. Your first selected stage becomes the starting plan; Free Little Wins includes one child profile.</p><form id="companionSetup"><label for="setupName">Child’s Nickname (Optional)</label><input id="setupName" name="nickname" maxlength="30" autocomplete="off"><label for="setupStages">Children’s Age Stages</label><select id="setupStages" name="stages" multiple size="3">${stages.map((s,i)=>`<option value="${i}" ${i===state.age?'selected':''}>${esc(s[0])}</option>`).join('')}</select><p class="fine">You can select more than one age stage.</p><label class="meal-prep-check"><input name="support" type="checkbox"> Neurodivergent-Friendly Starting Plan</label><label class="meal-prep-check"><input name="quiet" type="checkbox"> Prefer Gentle, Low-Noise Ideas</label><div class="activity-actions"><button type="submit">Make My Starting Plan</button><button type="button" data-skip-setup>Skip For Now</button></div></form></section>`}
function todayRoutines(){const p=getDailyPlan(),low=!!p.lowEnergy;const types=['morning','afternoon','evening'];return `<section class="card today-routines"><h3>Today’s Routines</h3><p class="fine">${esc(stages[state.age][0])}${state.support[scope()]?' · Supported plan':''}</p>${types.map(type=>{let list=getList(type);if(state.support[scope()])list=type==='morning'?list.slice(0,1):[];if(!list.length)return '';const complete=list.filter(x=>checked(type,x.id)).length;const focused=low&&state.age>1?list.filter(x=>!checked(type,x.id)).slice(0,1):list;return `<div class="routine-summary"><h4>${routineLabel(type)} <small>${complete}/${list.length}</small></h4>${focused.map((x,i)=>`<label class="meal-prep-check"><input type="checkbox" data-type="${type}" data-id="${esc(x.id)}" ${checked(type,x.id)?'checked':''}> ${esc(x.text)}</label>`).join('')||'<p class="fine">This routine is complete.</p>'}</div>`}).join('')}<button type="button" data-go="routines">Open Full Routines</button></section>`}
function ideaPanel(view='today'){const params=new URLSearchParams(location.search),id=params.get('idea'),idea=ideaCatalog.find(x=>x.id===id);if(!id)return '';if(idea&&ideaView(idea.kind)!==view)return '';if(!idea&&view!=='today')return '';if(!idea)return ideaCatalog.length?'<p class="card">That idea is unavailable. <a href="https://littlewinsparentclub.com/index.html#articles">Choose another guide.</a></p>':'<p class="card">Loading your article idea…</p>';return `<section class="card idea-review"><p class="kicker">FROM THE COMPANION BLOG</p><h2>Use This Idea</h2><h3>${esc(idea.title)}</h3><p>${esc(idea.text)}</p><p class="fine">Suggested ${esc(idea.kind)} · review it for your family’s needs.</p><div class="activity-actions"><button type="button" data-import-idea="${esc(idea.id)}">Add ${idea.kind==='meal'?'Meal':'Idea'} To Today</button><a href="${esc(idea.source)}">Read The Guide</a></div><p class="fine">Added ideas are part of your daily plan. Custom child checklists remain a Family Planner feature.</p></section>`}
function importedIdeas(view='today'){const p=getDailyPlan();if(!Array.isArray(p.ideas))p.ideas=[];const items=p.ideas.filter(x=>ideaView(x.kind)===view);return items.length?`<section class="card"><h3>Ideas I’m Trying</h3>${items.map(x=>`<div class="imported-idea"><span class="kicker">${esc(x.kind)}</span><label class="meal-prep-check"><input type="checkbox" data-import-complete="${esc(x.id)}" ${x.done?'checked':''}> ${esc(x.title)}</label><p>${esc(x.text)}</p><a href="${esc(safeCompanionLink(x.source))}">Original Guide</a><button type="button" data-remove-idea="${esc(x.id)}">Remove</button></div>`).join('')}</section>`:''}
function groceries(){if(!state.grocery||typeof state.grocery!=='object')state.grocery={meals:[],items:[]};if(!Array.isArray(state.grocery.meals))state.grocery.meals=[];if(!Array.isArray(state.grocery.items))state.grocery.items=[];return state.grocery}
function addMeal(id){const r=recipeCatalog.find(x=>x.id===id);if(!r){toast('Recipe unavailable. Reload to try again.');return}const g=groceries();if(!g.meals.includes(id)){g.meals.push(id);for(const text of r.ingredients){const key=text.trim().toLowerCase().replace(/\s+/g,' '),item=g.items.find(x=>x.key===key);if(item){if(!item.sources.includes(id))item.sources.push(id);}else g.items.push({id:crypto.randomUUID(),key,text,sources:[id],done:false});}}getDailyPlan().dinner=r.title;save();renderDailySections();toast('Meal added. Review quantities in your grocery list.');}
function groceryCard(){const g=groceries(),id=new URLSearchParams(location.search).get('meal'),meal=recipeCatalog.find(x=>x.id===id);return `<section class="card grocery-card"><span class="kicker">3 · SHOP WITH LESS GUESSWORK</span><h3>Grocery List</h3><p>Add a recipe in the Recipes section to collect its ingredients here. Edit amounts, add your own items, and check off what you already have or buy.</p>${meal?`<p>From the blog: <strong>${esc(meal.title)}</strong></p><button type="button" data-add-meal="${esc(meal.id)}">Add This Meal &amp; Ingredients</button>`:''}<div class="chosen-meals">${g.meals.map(id=>{const r=recipeCatalog.find(x=>x.id===id);return r?`<p>${esc(r.title)} <button type="button" data-remove-meal="${esc(id)}">Remove Meal</button></p>`:''}).join('')}</div><p class="fine">Ingredients with exactly matching text are combined. Different quantities stay separate so you can adjust amounts. Check allergens, your pantry, and serving needs.</p>${g.items.map((x,i)=>`<div class="grocery-row"><input type="checkbox" aria-label="Bought ${esc(x.text)}" data-grocery-check="${esc(x.id)}" ${x.done?'checked':''}><input aria-label="Shopping item ${i+1}" maxlength="180" value="${esc(x.text)}" data-grocery-edit="${esc(x.id)}"><button type="button" data-grocery-remove="${esc(x.id)}">Remove</button></div>`).join('')||'<p>No items yet. Add a meal or your own item.</p>'}<form id="groceryAdd"><label for="groceryText">Add Your Own Item</label><div class="daily-add-row"><input id="groceryText" maxlength="180" required><button type="submit">Add Item</button></div></form><button type="button" data-clear-bought>Remove Bought Items</button></section>`}
function renderDailySections(){const p=getDailyPlan();if($('dailyFunny'))$('dailyFunny').textContent=funny[seed%funny.length];if($('motivation'))$('motivation').textContent=encouragement[seed%encouragement.length];$('today-content').innerHTML=`<div class="section-head today-start-heading"><div><p class="today-date">${new Date().toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'})}</p><h2 id="today-heading">Today’s Little Wins</h2><p>A few tasks, a dinner plan, and one idea for your crew.</p></div><label class="low-energy-choice"><input type="checkbox" data-low-energy ${p.lowEnergy?'checked':''}> Low-Energy Day</label></div>${p.lowEnergy?'<p class="low-energy-note">Choose one essential, keep dinner easy, and leave room for rest. Essential care and safety still come first.</p>':''}${mealTaskView?'<section class="meal-task-return"><p><strong>Your Meal Prep Tasks</strong> · Check off a step or use an optional timer.</p><button type="button" data-return-meals>Back To Meals &amp; Recipes</button></section>':''}<div class="today-start-grid">${dailyPlanCard()}${dayDinnerSummary()}${todayActivityIdea()}</div>${ideaPanel()}${importedIdeas()}${lowEnergyWellbeing()}`;$('meal-prep-section').innerHTML=`<div class="section-head"><div><h2 id="meal-heading">Meal Prep &amp; Recipes</h2><p>Choose meals once. Bring the ingredients together.</p></div><button type="button" data-go="today">Back To Today’s Little Wins</button></div>${ideaPanel('meals')}<div class="meal-prep-grid">${taskMealCard()}<section class="card daily-plan meal-prep-card"><span class="kicker">2 · MAKE DINNER EASIER</span><h3>Meal Prep</h3><p>Write dinner, add prep notes, and check off the steps.</p><label for="dailyDinner">Tonight’s Dinner</label><input id="dailyDinner" maxlength="200" value="${esc(p.dinner)}" placeholder="e.g. Tacos with fruit"><label for="mealIngredients">Prep Notes</label><textarea id="mealIngredients" maxlength="500" rows="3">${esc(p.ingredients)}</textarea><h3>A Little Prep</h3>${['Choose a recipe for tonight','Check the ingredients','Set out the tools you need'].map((text,i)=>`<label class="meal-prep-check"><input type="checkbox" data-meal-prep="prep-${i}" ${p.prep['prep-'+i]?'checked':''}> ${text}</label>`).join('')}<div class="meal-task-explainer"><details><summary>How Prep Tasks Work</summary><p>It adds “Prep: ${esc(p.dinner)||'Plan and prepare dinner'}” to Today’s Little Wins. The suggested timer is 15 minutes (5 on a Low-Energy Day); it only runs when you start it. You can edit, schedule, or complete the task there.</p></details><div class="activity-actions"><button type="button" data-meal-prep-task>Add A Meal Prep Task</button><button type="button" data-open-meal-tasks>View Meal Prep Tasks</button></div></div></section>${groceryCard()}</div>${importedIdeas('meals')}`;}
async function loadUnifiedFavorites(){try{const r=await fetch('/api/favorites');const j=await r.json();if(!r.ok)throw Error(j.error);unifiedFavoriteItems=j.items;favoriteStatus='Articles, activities, and recipes saved to this companion account.';if(tab==='favorites')render();}catch(e){favoriteStatus=e.message||'Favorites unavailable.';if(tab==='favorites')render();}}
function unifiedFavoritesView(){const items=unifiedFavoriteItems.filter(x=>favoriteFilter==='all'||x.kind===favoriteFilter);return `<p class="favorites-note">${esc(favoriteStatus)}</p><div class="favorites-filters">${['all','article','activity','recipe'].map(kind=>`<button type="button" data-favorite-filter="${kind}" aria-pressed="${favoriteFilter===kind}">${kind==='all'?'All':kind[0].toUpperCase()+kind.slice(1)+'s'}</button>`).join('')}<button type="button" data-refresh-unified>Refresh</button></div><div class="activity-grid">${items.map(x=>x.kind==='activity'?activity(x.activity,x.stage):`<article class="card"><span class="kicker">${esc(x.kind)}</span><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p><div class="activity-actions"><a href="${esc(x.url)}">${x.kind==='recipe'?'Read Recipe':'Read Article'}</a>${x.kind==='recipe'?`<button type="button" data-add-meal="${esc(x.id)}">Add To Meal Plan</button>`:`<a href="index.html?idea=${esc(x.id)}">Use This Idea</a>`}<button type="button" data-remove-unified="${esc(x.id)}" data-kind="${x.kind}">Remove From Favorites</button></div></article>`).join('')||'<p class="card">Save an article, activity, or recipe to find it here.</p>'}</div>`}
async function removeUnified(id,kind){try{const r=await fetch('/api/'+(kind==='article'?'articles':'recipes')+'/favorites',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(kind==='article'?{articleId:id}:{recipeId:id})});const j=await r.json();if(!r.ok)throw Error(j.error);await loadUnifiedFavorites();}catch(e){toast(e.message||'Unable to remove this favorite.');}}
function hubClick(e){const stepsLink=e.target.closest('[data-open-little-steps]');if(stepsLink){e.preventDefault();captureDailyPlan();mealTaskView=false;tab='activities';render();scrollToCompanionSection(true);return true;}if(taskTimerClick(e))return true;const b=e.target.closest('button');if(!b)return false;const d=b.dataset;
 if(d.openMealTasks!==undefined){captureDailyPlan();mealTaskView=true;tab='today';render();scrollToCompanionSection();return true;}if(d.returnMeals!==undefined){captureDailyPlan();mealTaskView=false;tab='meals';render();scrollToCompanionSection();return true;}
 if(d.addMeal){addMeal(d.addMeal);tab='meals';render();return true}if(d.addChosenMeal!==undefined){addMeal($('mealChoice').value);return true}
 if(d.removeMeal){const g=groceries();g.meals=g.meals.filter(x=>x!==d.removeMeal);g.items=g.items.filter(x=>{x.sources=x.sources.filter(s=>s!==d.removeMeal);return x.sources.length||x.manual});save();renderDailySections();return true;}
 if(d.groceryRemove){groceries().items=groceries().items.filter(x=>x.id!==d.groceryRemove);save();renderDailySections();return true;}
 if(d.clearBought!==undefined){groceries().items=groceries().items.filter(x=>!x.done);save();renderDailySections();return true;}
 if(d.importIdea){const idea=ideaCatalog.find(x=>x.id===d.importIdea);if(!idea)return true;if(idea.kind==='meal')addMeal(idea.recipeId);const p=getDailyPlan();if(!p.ideas)p.ideas=[];if(!p.ideas.some(x=>x.id===idea.id))p.ideas.push({...idea,done:false});save();render();toast('Idea added to your '+(ideaView(idea.kind)==='meals'?'meal plan':'Little Steps, Big Wins')+'.');return true;}
 if(d.removeIdea){getDailyPlan().ideas=getDailyPlan().ideas.filter(x=>x.id!==d.removeIdea);save();render();return true;}
 if(d.skipSetup!==undefined){state.setup={done:true,skipped:true};save();render();return true;}
 if(d.favoriteFilter){favoriteFilter=d.favoriteFilter;render();return true;}if(d.refreshUnified!==undefined){loadUnifiedFavorites();return true;}if(d.removeUnified){removeUnified(d.removeUnified,d.kind);return true;}
 return false;
}
function hubChange(e){const d=e.target.dataset;if(d.recipeChoice!==undefined){chosenMealId=e.target.value;const r=recipeCatalog.find(x=>x.id===chosenMealId);if(r){$('chosenRecipeSteps').href=r.source;$('chosenRecipeSteps').textContent='Ingredients & Steps: '+r.title;}return true;}if(d.todoEdit||d.taskDuration){captureDailyPlan();renderDailySections();return true;}if(d.activityFilter){activityFilters[d.activityFilter]=e.target.value;offset=0;render();scrollToCompanionSection();return true;}if(d.lowEnergy!==undefined){getDailyPlan().lowEnergy=e.target.checked;if(e.target.checked)applyLowEnergyPlan();else{const p=getDailyPlan(),r=recipeCatalog.find(x=>x.id===p.lowEnergyRecipe);if(r&&p.dinner===r.title&&typeof p.regularDinner==='string')p.dinner=p.regularDinner;p.lowEnergyMealActive=false;}save();render();return true}if(d.groceryCheck){const x=groceries().items.find(x=>x.id===d.groceryCheck);if(x){x.done=e.target.checked;save()}return true}if(d.importComplete){const x=getDailyPlan().ideas.find(x=>x.id===d.importComplete);if(x){x.done=e.target.checked;save()}return true}return false;}
function hubInput(e){if(e.target.id==='todayDinner'){getDailyPlan().dinner=e.target.value.slice(0,200);if($('dailyDinner'))$('dailyDinner').value=getDailyPlan().dinner;save();return true;}if(taskTimerInput(e))return true;if(e.target.dataset.groceryEdit){const x=groceries().items.find(x=>x.id===e.target.dataset.groceryEdit);if(x){x.text=e.target.value.slice(0,180);x.key=x.text.trim().toLowerCase().replace(/\s+/g,' ');save()}return true;}return false;}
function hubSubmit(e){const f=e.target;if(f.id==='dailyTodoForm'){captureDailyPlan();const text=f.querySelector('input').value.trim();if(text)addTimedTask(mealTaskView?'Prep: '+text:text,Number($('taskNewMinutes').value)||15);return true;}if(f.id==='groceryAdd'){const text=f.querySelector('input').value.trim();if(text){const g=groceries();if(g.items.length>=150){toast('Keep the list to 150 items or fewer.');return true}g.items.push({id:crypto.randomUUID(),key:text.toLowerCase(),text:text.slice(0,180),sources:[],manual:true,done:false});save();renderDailySections()}return true;}
 if(f.id==='companionSetup'){const ages=[...f.elements.stages.selectedOptions].map(x=>Number(x.value));if(!ages.length){toast('Choose at least one age stage.');return true}state.setup={done:true,ages,support:f.elements.support.checked,quiet:f.elements.quiet.checked};const name=f.elements.nickname.value.trim();if(name&&!state.children.length){const child={id:crypto.randomUUID(),name:name.slice(0,30),age:ages[0]};state.children.push(child);state.selected=child.id;}state.age=ages[0];state.support[scope()]=state.setup.support;const p=getDailyPlan();if(!p.goal)p.goal='Try one small step in our starting routine.';save();render();toast('Starting plan ready.');return true;}return false;
}

loadCompanion();loadUnifiedFavorites();

function safeCompanionLink(url){try{const u=new URL(url);return u.protocol==='https:'&&u.hostname==='littlewinsparentclub.com'?u.href:'https://littlewinsparentclub.com';}catch{return 'https://littlewinsparentclub.com';}}

$('loadSavedCompanion').onclick=()=>{try{localStorage.setItem('littleWins.recovery',localStorage.getItem('littleWins.pending')||JSON.stringify(state));localStorage.removeItem('littleWins.pending');}catch{}location.reload();};

function taskMinutes(x){const value=Number(x.minutes);return Number.isFinite(value)?Math.max(1,Math.min(240,Math.round(value))):15}
function timerCaption(x,now=Date.now()){const t=x.timer;if(!t)return 'No timer set';if(t.status==='scheduled')return 'Starts '+new Date(t.startAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+' · '+taskMinutes(x)+' min';if(t.status==='running'){const s=Math.max(0,Math.ceil((t.endAt-now)/1000));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')+' remaining';}if(t.status==='paused'){const s=Math.ceil(t.remaining/1000);return 'Paused · '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}return t.status==='ended'?'Timer finished':'Timer stopped';}
function taskRow(x,i){const status=x.timer?.status,active=['scheduled','running','paused'].includes(status),clock=x.timer?timerCaption(x):taskMinutes(x)+' min · optional timer';return `<article class="todo-task simple-task ${x.done?'task-done':''} ${active?'timer-active':''}"><div class="simple-task-heading"><input type="checkbox" id="daily-todo-${i}" aria-label="Mark ${esc(x.text)} ${x.done?'unfinished':'complete'}" data-daily-todo="${esc(x.id)}" ${x.done?'checked':''}><label class="simple-task-title" for="daily-todo-${i}">${esc(x.text)}</label></div>${!x.done?`<div class="simple-timer-row"><output data-timer-task="${esc(x.id)}">${esc(clock)}</output>${status==='scheduled'?'<span class="timer-scheduled-label">Scheduled</span>':`<button type="button" class="${status==='running'?'secondary':'primary'}" ${status==='running'?`data-task-pause="${esc(x.id)}"`:status==='paused'?`data-task-resume="${esc(x.id)}"`:`data-task-start="${esc(x.id)}"`}>${status==='running'?'Pause':status==='paused'?'Resume':status==='ended'?'Start Again':'Start Timer'}</button>`}</div>`:''}<details class="task-options"><summary>Task Options</summary><label for="task-edit-${i}">Task Name</label><input id="task-edit-${i}" maxlength="120" value="${esc(x.text)}" data-todo-edit="${esc(x.id)}"><label for="task-minutes-${i}">Timer Length (Minutes)</label><input id="task-minutes-${i}" type="number" min="1" max="240" value="${taskMinutes(x)}" data-task-duration="${esc(x.id)}" ${active?'disabled':''}>${!active&&!x.done?`<div class="task-schedule-option"><label for="task-start-${i}">Start Later (Optional)</label><p class="fine">Scheduled alerts also need the companion to stay open.</p><input id="task-start-${i}" type="datetime-local" data-task-start-at="${esc(x.id)}" value="${esc(x.startInput||'')}"><button type="button" class="secondary" data-task-schedule="${esc(x.id)}">Schedule Timer</button></div>`:''}<div class="task-options-actions">${active?`<button type="button" class="secondary" data-task-stop="${esc(x.id)}">${status==='scheduled'?'Cancel Scheduled Timer':'Stop Timer'}</button>`:''}<button type="button" class="secondary" data-delete-todo="${esc(x.id)}">Remove Task</button></div></details></article>`}
function dailyPlanCard(){const p=getDailyPlan(),tasks=mealTaskView?p.todos.filter(x=>/^Prep: /i.test(x.text)):p.todos,pending=tasks.filter(x=>!x.done&&(!p.lowEnergy||x.lowEnergy||['running','paused','scheduled'].includes(x.timer?.status))),other=p.lowEnergy?tasks.filter(x=>!x.done&&!x.lowEnergy&&!['running','paused','scheduled'].includes(x.timer?.status)):[],completed=tasks.filter(x=>x.done),row=x=>taskRow(x,p.todos.indexOf(x));pending.sort((a,b)=>Number(['running','paused','scheduled'].includes(b.timer?.status))-Number(['running','paused','scheduled'].includes(a.timer?.status)));return `<section class="card daily-plan todo-plan simplified-plan planner-page" aria-labelledby="planner-page-title"><header class="planner-page-head"><p class="kicker">${mealTaskView?'IN THE KITCHEN':'ONE LITTLE WIN AT A TIME'}</p><h3 id="planner-page-title">${mealTaskView?'My Meal Prep Planner':'My Daily Planner'}</h3></header><p class="task-list-intro">Add a task, check it off, or start an optional timer.</p><form id="dailyTodoForm" class="simple-add-task"><label for="dailyTodoText">What’s Next?</label><div class="simple-add-row"><input id="dailyTodoText" maxlength="120" placeholder="${mealTaskView?'e.g. Chop vegetables or pack tomorrow’s lunch':'e.g. Tidy toys or take a break'}" required><button type="submit" class="primary">Add Task</button></div><details class="new-task-timer"><summary>Choose A Timer Length (Optional)</summary><label for="taskNewMinutes">Minutes</label><input id="taskNewMinutes" type="number" min="1" max="240" value="15"><p class="fine">A new task starts with a 15-minute suggestion. No timer runs until you start or schedule it.</p></details></form><details class="daily-goal-option" ${p.goal?'open':''}><summary>One Goal For Today (Optional)</summary><label class="sr-only" for="dailyGoal">One Goal For Today</label><textarea id="dailyGoal" rows="2" maxlength="300" placeholder="What would make today easier?">${esc(p.goal)}</textarea></details><div class="task-list-count">${pending.length} ${pending.length===1?'task':'tasks'} left${completed.length?' · '+completed.length+' done':''}</div><div class="daily-todos">${pending.slice(0,3).map(row).join('')||`<p class="task-empty">${p.lowEnergy?'Your essentials are clear. Rest or choose one small task.':completed.length?'Your list is clear. Let that be a little win.':'Start with one small task. You don’t have to plan it all.'}</p><div class="planner-blank-lines" aria-hidden="true"><span></span><span></span><span></span></div>`}</div>${pending.length>3?`<details class="task-group more-tasks"><summary>More Tasks (${pending.length-3})</summary>${pending.slice(3).map(row).join('')}</details>`:''}${other.length?`<details class="task-group"><summary>Other Tasks (${other.length})</summary><p class="fine">These can wait on a low-energy day.</p>${other.map(row).join('')}</details>`:''}${completed.length?`<details class="task-group completed-tasks"><summary>Completed (${completed.length})</summary>${completed.map(row).join('')}</details>`:''}${timerOptionsCard()}</section>`}
function timedActivitiesCard(){const candidates=(getDailyPlan().lowEnergy?[stages[state.age][2].map((x,i)=>({i,time:parseInt(x.split('|')[2])||15})).sort((a,b)=>a.time-b.time)[0].i]:filteredActivities());return `<section class="card timed-ideas"><h3>Choose A Timed Activity</h3><p class="fine">${esc(stages[state.age][0])} · activity time is a flexible suggestion.</p>${activityFilterControls()}${candidates.map(i=>{const [title,body,time]=stages[state.age][2][i].split('|');return `<div class="timed-idea"><h4>${esc(title)} <small>${getDailyPlan().lowEnergy?'5 min · optional':esc(time)}</small></h4><p>${esc(body)}</p>${activityDetails(state.age,i)}<button type="button" data-timed-idea="${i}">Add To My Tasks</button></div>`}).join('')}${state.support[scope()]?'':'<button type="button" data-shuffle-timed>Shuffle Another Activity</button>'}</section>`}
function taskMealCard(){const p=getDailyPlan(),chosen=recipeCatalog.find(r=>r.id===chosenMealId)||recipeCatalog.find(r=>r.id===(p.lowEnergy?p.lowEnergyRecipe:null))||recipeCatalog[0];return `<section class="card task-meal recipe-choice-card"><span class="kicker">1 · FIND SOMETHING TO EAT</span><h3>Recipes</h3><p>Choose a meal below, then add it to your plan. Its ingredients go into your editable grocery list.</p><label for="taskMealChoice">Pick A Recipe</label><select id="taskMealChoice" data-recipe-choice>${['Breakfast','Lunch','Dinner'].map(kind=>`<optgroup label="${kind} Ideas">${recipeCatalog.filter(r=>r.mealType===kind).map(r=>`<option value="${esc(r.id)}" ${chosen?.id===r.id?'selected':''}>${esc(r.title)}</option>`).join('')}</optgroup>`).join('')}</select><div class="activity-actions"><button type="button" data-task-add-meal ${recipeCatalog.length?'':'disabled'}>Add Meal &amp; Grocery Items</button><a class="primary" id="chosenRecipeSteps" href="${esc(chosen?.source||'https://littlewinsparentclub.com/picky-eaters.html')}">See This Meal’s Ingredients &amp; Steps</a></div><p class="fine">Photos, ingredients, and preparation steps are in the recipe collection.</p><a href="https://littlewinsparentclub.com/picky-eaters.html">Browse All Blog Recipes</a></section>`}

function timerOptionsCard(){return `<div class="simple-alert-area"><p class="timer-limit-note">Timer alerts need the companion to stay open.</p><details class="timer-options"><summary>Sound &amp; Alerts <span class="sound-state">${timerUI.sound?'Sound On':'Sound Off'}</span></summary><div class="alert-settings-buttons"><button type="button" class="secondary" data-toggle-sounds>${timerUI.sound?'Turn Sound Off':'Turn Sound On'}</button><button type="button" class="secondary" data-enable-notifications>Allow Notifications</button></div><p class="fine">Visual alerts are on. Sound and device notifications are optional. Phones may pause alerts in the background; use your phone’s Clock for alarms when the companion is closed.</p><p id="timerAlarmStatus" class="timer-alert-status" role="status">${esc(timerUI.message)}</p></details></div>`}
async function unlockTaskAudio(){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){timerUI.message='Sound alerts are unavailable in this browser. Visual alerts still work.';return false}try{if(!timerUI.audio)timerUI.audio=new Audio();await timerUI.audio.resume();return true;}catch{timerUI.message='Sound could not start. Tap Enable Sound Alerts again.';return false}}
function soundTaskAlert(){if(!timerUI.sound||!timerUI.audio)return;try{const ctx=timerUI.audio;for(let i=0;i<3;i++){const oscillator=ctx.createOscillator(),gain=ctx.createGain(),at=ctx.currentTime+i*.28;oscillator.type='sine';oscillator.frequency.value=660;gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.13,at+.02);gain.gain.linearRampToValueAtTime(0,at+.2);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start(at);oscillator.stop(at+.22);}}catch{}}
function announceTask(x,phase){const message=(phase==='start'?'Starting: ':'Finished: ')+x.text;timerUI.message=message;soundTaskAlert();if($('timerAlarmStatus'))$('timerAlarmStatus').textContent=timerUI.message;toast(timerUI.message);if(typeof Notification!=='undefined'&&Notification.permission==='granted'&&navigator.serviceWorker?.ready)navigator.serviceWorker.ready.then(reg=>reg.showNotification('Little Wins Parenting Companion',{body:message,tag:'littlewins-'+x.id+'-'+phase})).catch(()=>{});}
function startTask(x,at=Date.now()){if(!companionSync.ready){toast('Load your saved companion plan before starting a timer.');return;}const now=Date.now();x.timer={status:at>now?'scheduled':'running',startAt:at,endAt:at+taskMinutes(x)*60000,remaining:0,startAlerted:at<=now,endAlerted:false};if(at<=now)announceTask(x,'start');save();renderDailySections();}
function tickTaskTimers(now=Date.now()){if(!companionSync.ready)return;let changed=false;for(const p of Object.values(state.dailyPlans||{})){for(const x of p.todos||[]){const t=x.timer;if(!t||x.done)continue;if((t.status==='scheduled'||t.status==='running')&&now>=t.endAt){t.status='ended';if(!t.endAlerted){t.endAlerted=true;announceTask(x,'end')}changed=true;}else if(t.status==='scheduled'&&now>=t.startAt){t.status='running';if(!t.startAlerted){t.startAlerted=true;announceTask(x,'start')}changed=true;}}}if(changed){save();renderDailySections();}document.querySelectorAll('[data-timer-task]').forEach(out=>{const x=getDailyPlan().todos.find(t=>t.id===out.dataset.timerTask);if(x)out.textContent=x.timer?timerCaption(x,now):taskMinutes(x)+' min · optional timer';});}
function taskTimerClick(e){const b=e.target.closest('button');if(!b)return false;const d=b.dataset;const id=d.taskStart||d.taskSchedule||d.taskPause||d.taskResume||d.taskStop;const x=getDailyPlan().todos.find(x=>x.id===id);
 if(id){if(!x)return true;if(d.taskStart){if(!x.done)startTask(x);}else if(d.taskSchedule){const at=new Date(x.startInput).getTime();if(!Number.isFinite(at)||at<=Date.now()){toast('Choose a future start time, or use Start Now.');return true}startTask(x,at);toast('Start and finish alerts set while the companion is open.');}else if(d.taskPause&&x.timer?.status==='running'){x.timer.remaining=Math.max(0,x.timer.endAt-Date.now());x.timer.status='paused';save();renderDailySections();}else if(d.taskResume&&x.timer?.status==='paused'){x.timer.endAt=Date.now()+x.timer.remaining;x.timer.status='running';save();renderDailySections();}else if(d.taskStop&&x.timer){x.timer.status='stopped';save();renderDailySections();}return true;}
 if(d.toggleSounds!==undefined){if(timerUI.sound){timerUI.sound=false;timerUI.message='Sound alerts muted.';renderDailySections();}else unlockTaskAudio().then(ok=>{timerUI.sound=ok;timerUI.message=ok?'Sound alerts are on while this companion is open.':timerUI.message;renderDailySections();});return true;}
 if(d.enableNotifications!==undefined){if(typeof Notification==='undefined'||typeof Notification.requestPermission!=='function'){timerUI.message='Device notifications are unavailable here. Use visual alerts or sound while the companion is open.';renderDailySections();}else Notification.requestPermission().then(permission=>{timerUI.message=permission==='granted'?'Device notifications allowed. The page still needs to stay open for scheduled alerts.':'Device notifications were not enabled. Visual alerts are still available.';renderDailySections();}).catch(()=>{timerUI.message='Notifications are unavailable here. Try the installed companion, or use sound alerts.';renderDailySections();});return true;}
 if(d.timedIdea!==undefined){const i=Number(d.timedIdea);if(!stages[state.age][2][i])return true;const [title,body,time]=stages[state.age][2][i].split('|');addTimedTask(title,getDailyPlan().lowEnergy?5:parseInt(time)||15);tab='today';render();scrollToCompanionSection();return true;}
 if(d.shuffleTimed!==undefined){activityChoices=nextActivitySet(state.age);renderDailySections();return true;}
 if(d.taskAddMeal!==undefined){addMeal($('taskMealChoice').value);return true;}
 if(d.mealPrepTask!==undefined){captureDailyPlan();addTimedTask(getDailyPlan().dinner?'Prep: '+getDailyPlan().dinner:'Prep: Plan and prepare dinner',getDailyPlan().lowEnergy?5:15);return true;}
 return false;
}
function addTimedTask(text,minutes){const p=getDailyPlan();if(p.todos.length>=30){toast('Keep your daily list to 30 tasks or fewer.');return}p.todos.push({id:crypto.randomUUID(),text:text.slice(0,120),minutes:Math.max(1,Math.min(240,minutes)),done:false,lowEnergy:!!p.lowEnergy});save();renderDailySections();toast('Added to your tasks. Tap Start Timer when you’re ready.');}
function taskTimerInput(e){const d=e.target.dataset,x=getDailyPlan().todos.find(x=>x.id===(d.todoEdit||d.taskDuration||d.taskStartAt));if(!x)return false;if(d.todoEdit)x.text=e.target.value.slice(0,120);else if(d.taskDuration){if(['scheduled','running','paused'].includes(x.timer?.status))return true;x.minutes=Math.max(1,Math.min(240,Number(e.target.value)||15));}else if(d.taskStartAt)x.startInput=e.target.value;else return false;save();return true;}

setInterval(()=>tickTaskTimers(),1000);
function applyLowEnergyPlan(){const p=getDailyPlan();if(!p.lowEnergyAuto){const tasks=[{text:'One small essential: choose what matters most',minutes:5},{text:'A two-minute mental reset: pause, rest, or ask for help',minutes:2}];const picks=stages[state.age][2].map((text,i)=>({text,i,time:parseInt(text.split('|')[2])||15})).sort((a,b)=>a.time-b.time);for(const task of tasks){if(p.todos.length<30)p.todos.push({...task,id:crypto.randomUUID(),done:false,lowEnergy:true});}p.lowEnergyAuto=true;}if(recipeCatalog.length){const recipe=recipeCatalog.find(r=>r.id==='easy-bean-tacos')||recipeCatalog.find(r=>r.id==='white-bean-toast')||recipeCatalog[0];if(!p.lowEnergyMealActive)p.regularDinner=p.dinner;p.lowEnergyMealActive=true;p.lowEnergyRecipe=recipe.id;p.dinner=recipe.title;}save();}


// Main navigation uses the existing family editor without reloading saved tasks.
document.querySelector('[data-open-family]')?.addEventListener('click',()=>{familyList();$('familyDialog').showModal()});

function organizeSections(view){
 const familyViews=['routines','activities','responsibilities'];
 const upgrade=document.querySelector('.family-planner-upgrade');if(upgrade)upgrade.hidden=!familyViews.includes(view);
 const childNav=document.querySelector('.child-tools-nav');if(childNav)childNav.hidden=!familyViews.includes(view);
 const careNav=document.querySelector('.parent-care-nav');if(careNav)careNav.hidden=!['selfcare','journal'].includes(view);
}
function dayDinnerSummary(){const p=getDailyPlan();return `<section class="card today-dinner-card"><p class="kicker">ONE LESS DECISION</p><h3>Tonight’s Dinner</h3><label class="sr-only" for="todayDinner">Tonight’s Dinner</label><input id="todayDinner" maxlength="200" value="${esc(p.dinner)}" placeholder="e.g. Tacos, leftovers, or something easy"><p class="fine">A simple meal counts.</p><button type="button" data-go="meals">Open Meals &amp; Recipes</button></section>`}
function todayActivityIdea(){const list=stages[state.age][2],i=state.support[scope()]?0:(seed+offset)%list.length,[title,body,time]=list[i].split('|');return `<section class="card today-activity-card"><p class="kicker">ONE IDEA FOR YOUR CREW</p><h3>${esc(title)}</h3><p>${esc(body)}</p><p class="fine">${esc(stages[state.age][0])} · ${esc(time)}</p><details class="today-activity-help"><summary>Materials &amp; Ways To Adapt</summary>${activityDetails(state.age,i)}</details><div class="activity-actions"><button type="button" data-timed-idea="${i}">Add To Today</button><a class="secondary today-steps-link" href="index.html?view=activities#stage-panel" data-open-little-steps>Open Little Steps, Big Wins</a></div></section>`}

document.querySelectorAll('[data-account-family]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();tab='routines';render();document.querySelectorAll('.account-menu').forEach(menu=>menu.open=false);familyList();$('familyDialog').showModal()}));

function ideaView(kind){return ({activity:'activities',routine:'routines',responsibility:'responsibilities',meal:'meals'})[kind]||'today'}

window.littleWinsTourView=function(view){const previous=tab;if(!['today','routines','activities','meals','selfcare','journal','favorites','club'].includes(view))return previous;captureDailyPlan();tab=view;render();return previous;};

$('multiplesMode').onchange=e=>{captureDailyPlan();state.multiplesMode=e.target.checked;save();render();toast(e.target.checked?'Multiples ideas selected.':'Individual ideas selected.');};

function scrollToCompanionSection(includeStage=false){
 const familyView=['activities','routines','responsibilities'].includes(tab);
 const targetId=tab==='today'?'today-content':tab==='meals'?'meal-prep-section':tab==='club'?'parent-club-section':includeStage&&familyView?'stage-panel':'content';
 requestAnimationFrame(()=>{
  const el=document.getElementById(targetId);if(!el||el.hidden)return;
  el.setAttribute('tabindex','-1');
  const quiet=document.body.classList.contains('calm-view')||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  el.focus({preventScroll:true});
  el.scrollIntoView({behavior:quiet?'auto':'smooth',block:'start'});
 });
}
function lowEnergyWellbeing(){return getDailyPlan().lowEnergy?`<details class="low-energy-help"><summary>A Gentler Plan For Your Mind &amp; Day</summary><ul><li>Choose one must-do; let less urgent jobs wait.</li><li>Take a quiet pause or a comfortable breath without forcing a breathing pattern.</li><li>Use a familiar easy meal and ask for one practical bit of help.</li><li>Notice what you managed; rest is part of the plan.</li></ul><p>These are wellbeing ideas, not mental-health treatment. <a href="https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health">NIMH Mental-Health Resources</a></p></details>`:''}

function loadParentClub(refresh=false){const frame=$('parentClubFrame');if(frame&&(refresh||!frame.getAttribute('src')))frame.setAttribute('src',frame.dataset.src);}
$('loadParentClub').onclick=()=>loadParentClub(true);

// Reach the daily plan directly without reloading or discarding input.
document.querySelector("[data-jump-today]")?.addEventListener("click",event=>{event.preventDefault();captureDailyPlan();mealTaskView=false;tab="today";render();scrollToCompanionSection();});
